  "stem": "某保險公司想估計颱風季的理賠損失分佈與 95 百分位的極端損失，但損失同時受風速、路徑、投保區域等多個隨機因素影響，無法寫出解析式。公司以隨機抽樣產生十萬組情境並逐一計算損失。此做法屬於下列哪一種方法？",
