  "stem": "某城市的共享單車停放點座標呈現幾條沿河岸的狹長帶狀群集，資料中還混有 GPS 飄移產生的零星雜訊點，且事先不知道應分成幾群。依指引對分群演算法的比較，最適合的方法為何？",
