  "stem": "團隊有 20 萬張標註好的醫學影像，要以 ImageNet 預訓練的 ResNet 做遷移學習。由於醫學影像與自然影像差異很大、且資料量充足，依遷移學習策略的選擇原則，最適合的做法為何？",
