  "stem": "某 RAG 系統把每份文件切成 2,000 token 的大片段。使用者問具體條款時，檢索回來的片段雖然包含答案，但九成內容是無關段落，LLM 常被干擾而答錯。在檢索前處理階段最直接的改善為何？",
